import { Button } from '@liulidesign/core/Button';

export function Variants() {
  return (
    <view className="flex-row flex-wrap gap-2">
      <Button label="Save changes" variant="primary" data-testid="primary" />
      <Button label="Preview" />
      <Button label="Skip" variant="ghost" />
      <Button label="Delete draft" variant="destructive" />
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';

export function Sizes() {
  return (
    <view className="flex-row flex-wrap items-center gap-2">
      <Button label="Small" size="sm" />
      <Button label="Medium" />
      <Button label="Large" size="lg" />
    </view>
  );
}

import { useView, type View } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';

type Actions = { publish(): Promise<void> };

/** `clickAction` takes a Logic action as it is; the button shows loading until it settles. */
export function AsyncAction() {
  const { actions } = useView() as View<Actions>;
  return <Button label="Publish" variant="primary" width="content" clickAction={() => actions.publish()} data-testid="publish" />;
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';

/** The reason is read after the label while disabled. Pass translated copy; Liuli ships none. */
export function DisabledWithReason() {
  const agreed = useLocal('agreed', false);
  return (
    <view className="gap-2">
      <Button
        label="Continue"
        variant="primary"
        width="fill"
        isDisabled={!agreed.value}
        disabledMessage="Accept the terms first"
        data-testid="continue"
      />
      <Button
        label={agreed.value ? 'Withdraw consent' : 'Accept the terms'}
        variant="ghost"
        onClick={() => agreed.set(!agreed.value)}
        data-testid="toggle-terms"
      />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { CheckboxInput } from '@liulidesign/core/CheckboxInput';

export function Basic() {
  const digest = useLocal('digest', true);
  return <CheckboxInput bind={digest} label="Weekly digest" description="A summary of your notes every Monday." data-testid="digest" />;
}

import { useLocal } from '@lingxia/view';
import { CheckboxInput } from '@liulidesign/core/CheckboxInput';

/** Owned by the app: the checkbox reports, the app decides. */
export function Controlled() {
  const accepted = useLocal('accepted', false);
  return (
    <CheckboxInput
      value={accepted.value}
      onChange={next => accepted.set(next)}
      label="I accept the terms of service"
      isRequired
      status={accepted.value ? undefined : { type: 'error', message: 'Accept the terms to create the account.' }}
      data-testid="terms"
    />
  );
}

import { useLocal } from '@lingxia/view';
import { CheckboxInput } from '@liulidesign/core/CheckboxInput';

export function Sizes() {
  const small = useLocal('small', false);
  const medium = useLocal('medium', true);
  const large = useLocal('large', false);
  return (
    <view className="gap-2">
      <CheckboxInput bind={small} label="Small" size="sm" />
      <CheckboxInput bind={medium} label="Medium" />
      <CheckboxInput bind={large} label="Large" size="lg" />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { Dialog } from '@liulidesign/core/Dialog';

/** A confirmation that interrupts: Escape and back cancel, a backdrop tap does not; the destructive action is last. */
export function Confirm() {
  const open = useLocal('open', false);
  const deleted = useLocal('deleted', false);
  return (
    <view className="gap-2">
      <Button label="Delete note" variant="destructive" width="content" onClick={() => open.set(true)} data-testid="open" />
      <text role="status" data-testid="outcome" className="text-sm text-muted">{deleted.value ? 'Deleted' : 'Not deleted'}</text>
      <Dialog
        isOpen={open.value}
        onOpenChange={next => open.set(next)}
        label="Delete this note?"
        description="It leaves every device you are signed in on."
        size="sm"
        isAlert
        dismissOn="closeRequest"
        data-testid="dialog"
        actions={
          <>
            <Button label="Cancel" onClick={() => open.set(false)} data-testid="cancel" />
            <Button label="Delete" variant="destructive" onClick={() => { deleted.set(true); open.set(false); }} data-testid="confirm" />
          </>
        }
      />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { TextInput } from '@liulidesign/core/TextInput';
import { Dialog } from '@liulidesign/core/Dialog';

/**
 * A short form. The draft lives outside the dialog, since closing discards the dialog's own state.
 * Only Escape and back cancel, so a stray backdrop tap does not lose the typing.
 */
export function Form() {
  const open = useLocal('open', false);
  const name = useLocal('name', '');
  return (
    <view className="gap-2">
      <Button label="Rename" width="content" onClick={() => open.set(true)} data-testid="open" />
      <Dialog
        isOpen={open.value}
        onOpenChange={next => open.set(next)}
        label="Rename notebook"
        closeLabel="Close"
        dismissOn="closeRequest"
        data-testid="dialog"
        actions={<Button label="Save" variant="primary" isDisabled={name.value.trim() === ''} onClick={() => open.set(false)} data-testid="save" />}
      >
        <TextInput bind={name} label="Name" hasAutoFocus enterKeyHint="done" onSubmit={() => open.set(false)} data-testid="name" />
      </Dialog>
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { DropdownMenu, DropdownMenuItem } from '@liulidesign/core/DropdownMenu';

/** A labelled trigger; the menu lines up with its start edge. */
export function Basic() {
  const order = useLocal('order', 'Name');
  return (
    <view className="flex-row items-center gap-3">
      <DropdownMenu label="Sort by" data-testid="sort">
        <DropdownMenuItem label="Name" onClick={() => order.set('Name')} data-testid="sort-name" />
        <DropdownMenuItem label="Last updated" description="Newest first" onClick={() => order.set('Last updated')} data-testid="sort-updated" />
        <DropdownMenuItem label="Size" onClick={() => order.set('Size')} />
      </DropdownMenu>
      <text data-testid="order" className="text-sm text-muted">{order.value}</text>
    </view>
  );
}

import { useLocal, type VectorPath } from '@lingxia/view';
import { DropdownMenu, DropdownMenuDivider, DropdownMenuItem } from '@liulidesign/core/DropdownMenu';

const dots: VectorPath[] = [{ d: 'M5 12h.01M12 12h.01M19 12h.01', fill: 'none', stroke: 'currentColor', strokeWidth: 3, strokeLinecap: 'round' }];
const trash: VectorPath[] = [{ d: 'M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinejoin: 'round' }];

/** An icon-only "more" menu at the end of a row, aligned to the row's end edge. */
export function More() {
  const removed = useLocal('removed', false);
  return (
    <view className="flex-row items-center gap-3">
      <text className="grow basis-0 text-base font-medium">{removed.value ? 'Removed' : 'Groceries'}</text>
      <DropdownMenu
        label="More actions"
        isLabelHidden
        icon={<vector aria-hidden paths={dots} viewBox={[0, 0, 24, 24]} className="size-5" />}
        variant="ghost"
        alignment="end"
        data-testid="more"
      >
        <DropdownMenuItem label="Rename" onClick={() => {}} />
        <DropdownMenuItem label="Share" onClick={() => {}} isDisabled />
        <DropdownMenuDivider />
        <DropdownMenuItem
          label="Delete"
          variant="destructive"
          icon={<vector aria-hidden paths={trash} viewBox={[0, 0, 24, 24]} className="size-4" />}
          onClick={() => removed.set(true)}
          data-testid="delete"
        />
      </DropdownMenu>
    </view>
  );
}

import { DropdownMenu, DropdownMenuItem } from '@liulidesign/core/DropdownMenu';

/** Rows that each carry a menu: every menu gets its own id, so no row needs one. */
export function InList() {
  const rows = ['Inbox', 'Archive'];
  return (
    <view className="gap-2">
      {rows.map(row => (
        <view key={row} className="flex-row items-center gap-3">
          <text className="grow basis-0 text-base">{row}</text>
          <DropdownMenu label={`${row} actions`} size="sm" data-testid={`menu-${row}`}>
            <DropdownMenuItem label="Open" onClick={() => {}} />
          </DropdownMenu>
        </view>
      ))}
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Field } from '@liulidesign/core/Field';

const periods = [
  { value: 'monthly', label: 'Monthly' },
  { value: 'yearly', label: 'Yearly' },
] as const;

/** A raw select takes Field's label, help and status until Liuli has its own. */
export function WrappedSelect() {
  const period = useLocal('period', '');
  return (
    <Field
      label="Billing period"
      description="You can change it later."
      status={period.value ? undefined : { type: 'warning', message: 'Choose a period to see the price.' }}
      isRequired
      data-testid="field"
    >
      {control => (
        <select
          bind={period}
          aria-label={control['aria-label']}
          aria-describedby={control['aria-describedby']}
          aria-invalid={control['aria-invalid']}
          aria-required={control['aria-required']}
          disabled={control.disabled}
          placeholder="Choose…"
          options={periods}
          data-testid="period"
          className="min-h-control-md px-3 rounded-control border border-line-strong bg-surface text-sm text-text"
        />
      )}
    </Field>
  );
}

import { useLocal } from '@lingxia/view';
import { TextInput } from '@liulidesign/core/TextInput';

/** Bound to a View-local cell: no Logic round trip per keystroke. */
export function Bound() {
  const email = useLocal('email', '');
  const invalid = email.value !== '' && !email.value.includes('@');
  return (
    <TextInput
      bind={email}
      label="Email"
      placeholder="you@example.com"
      type="email"
      autoComplete="email"
      autoCapitalize="none"
      enterKeyHint="next"
      description="We send the receipt here."
      status={invalid ? { type: 'error', message: 'Add the part after @, such as example.com.' } : undefined}
      isRequired
      data-testid="email"
    />
  );
}

import { useLocal, type VectorPath } from '@lingxia/view';
import { TextInput } from '@liulidesign/core/TextInput';

const magnifier: VectorPath[] = [
  { d: 'M10.5 4a6.5 6.5 0 1 0 0 13a6.5 6.5 0 1 0 0-13z', fill: 'none', stroke: 'currentColor', strokeWidth: 2 },
  { d: 'M15.5 15.5L20 20', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round' },
];

/** Controlled (`value` + `onChange`), with a leading icon and a clear button the app names. */
export function Search() {
  const query = useLocal('query', '');
  return (
    <TextInput
      value={query.value}
      onChange={next => query.set(next)}
      label="Search notes"
      isLabelHidden
      placeholder="Search notes"
      type="search"
      enterKeyHint="search"
      startIcon={<vector aria-hidden paths={magnifier} viewBox={[0, 0, 24, 24]} className="size-4" />}
      hasClear
      clearLabel="Clear search"
      data-testid="search"
    />
  );
}

import { useLocal } from '@lingxia/view';
import { TextInput } from '@liulidesign/core/TextInput';

export function Disabled() {
  const code = useLocal('code', 'LX-2041');
  return <TextInput bind={code} label="Invite code" isDisabled disabledMessage="Codes are fixed once sent." data-testid="code" />;
}
